def coerce_value(default_value: Any, env_value: str) -> Any:
    """Coerce environment variable value to match default type."""
    if isinstance(default_value, int):
        return int(env_value)
    elif isinstance(default_value, float):
        return float(env_value)
    elif isinstance(default_value, bool):
        true_values = {'true', '1', 'yes', 'y'}
        false_values = {'false', '0', 'no', 'n'}
        env_value_lower = env_value.lower()
        if env_value_lower in true_values:
            return True
        elif env_value_lower in false_values:
            return False
        else:
            raise ConfigError(f"Invalid boolean value '{env_value}'")
    else:
        # Assume string for anything else
        return env_value


def load_toml(toml_path: Optional[str]) -> Dict[str, Any]:
    """Load TOML file if it exists."""
    if not toml_path:
        return {}

    try:
        with open(toml_path, 'rb') as f:
            return tomllib.load(f)
    except FileNotFoundError:
        return {}
    except Exception as e:
        raise ConfigError(f"Error loading TOML file: {e}")


