import os
import pytest
from envcfg import load_config, ConfigError


def test_precedence():
    """Test that values follow the correct precedence."""
    defaults = {"a": 1, "b": {"c": 2}}

    # Test TOML overrides defaults
    with open("test.toml", "w") as f:
        f.write("[b]\nc = 3\n")

    config = load_config(defaults, "test.toml", "TEST")
    assert config["a"] == 1  # from defaults
    assert config["b"]["c"] == 3  # from TOML
    os.remove("test.toml")


def test_env_overrides():
    """Test that environment variables override everything."""
    defaults = {"a": 1, "b": {"c": 2}}
    env = {"TEST__B__C": "4"}

    config = load_config(defaults, None, "TEST", env)
    assert config["b"]["c"] == 4  # from env


def test_coercion():
    """Test type coercion from environment variables."""
    defaults = {
        "int_val": 0,
        "float_val": 0.0,
        "bool_val": False,
        "str_val": ""
    }
    env = {
        "TEST__INT_VAL": "42",
        "TEST__FLOAT_VAL": "3.14",
        "TEST__BOOL_VAL": "true",
        "TEST__STR_VAL": "hello"
    }

    config = load_config(defaults, None, "TEST", env)
    assert config["int_val"] == 42
    assert config["float_val"] == 3.14
    assert config["bool_val"] is True
    assert config["str_val"] == "hello"


def test_bool_coercion():
    """Test boolean coercion with various values."""
    defaults = {"bool_val": False}

    true_values = ["true", "1", "yes", "y"]
    false_values = ["false", "0", "no", "n"]

    for true_val in true_values:
        env = {"TEST__BOOL_VAL": true_val}
        config = load_config(defaults, None, "TEST", env)
        assert config["bool_val"] is True

    for false_val in false_values:
        env = {"TEST__BOOL_VAL": false_val}
        config = load_config(defaults, None, "TEST", env)
        assert config["bool_val"] is False


